#pragma once
// The data layout shared by every player skin model (shared/skin_<id>_model.h, generated by tools/skins/export_skin.py; docs/SKINS.md).
//
// A skin is a whole new body for Link that still moves with the game's own Link skeleton and animations. The mesh is stored exactly as the
// artist modelled it (metres, Y up, facing +Z, Link's left +X), every vertex weighted to one or two of the game's 21 Link limbs. The game
// binds it to the skeleton at run time (mod/Royale/features/Skins.inc): it poses the skeleton in a known standing pose, matches each limb's
// anchor point and bone direction below to the skeleton's joints, and from then on each limb's live matrix carries its vertices.
#include <cstdint>

namespace royale {
namespace skinmodel {

// The game's Link limbs, in joint-table order (PLAYER_LIMB_* - 1).
enum Limb : uint8_t { kRoot, kWaist, kLower, kRThigh, kRShin, kRFoot, kLThigh, kLShin, kLFoot, kUpper, kHead, kHat, kCollar,
                      kLShoulder, kLForearm, kLHand, kRShoulder, kRForearm, kRHand, kSheath, kTorso, kLimbCount };
inline constexpr const char* kLimbNames[kLimbCount] = { "root", "waist", "lower", "r_thigh", "r_shin", "r_foot", "l_thigh", "l_shin", "l_foot",
                                                        "upper", "head", "hat", "collar", "l_shoulder", "l_forearm", "l_hand", "r_shoulder",
                                                        "r_forearm", "r_hand", "sheath", "torso" };

constexpr int kTexW = 256, kTexH = 256, kTexBytes = kTexW * kTexH * 2;   // every texture is 256 x 256 RGBA16 (5-5-5-1, big-endian)

// A vertex: position (metres, the model's own standing pose), normal (x127), texel coordinate (1/32 texels), two limbs and the first one's weight (x255).
struct Vert { float x, y, z; int8_t nx, ny, nz; int16_t s, t; uint8_t b0, b1, w0; };
// A batch: up to 32 vertices loaded together and the triangles drawn from them (indices within the batch), one texture, one dominant limb
// (so the batch can be left out when the game draws its own limb there, e.g. a hand holding a sword).
struct Batch { uint16_t firstVert; uint8_t vertCount; uint16_t firstTri; uint16_t triCount; uint8_t tex; uint8_t limb; };
// Where a game limb's joint is on this model and which way its bone points (unit vector), in the model's space. `have` is 0 for limbs the model
// does not place (the trunk limbs: they follow the hips and shoulders).
struct Anchor { float x, y, z; float dx, dy, dz; uint8_t have; };

struct Model {
    const char* name;
    const Vert* verts;
    int vertCount;
    const Batch* batches;
    int batchCount;
    const uint8_t (*tris)[3];
    int triCount;
    const uint8_t* const* textures;   // textureCount pointers to kTexBytes each
    int textureCount;
    const Anchor* anchors;            // kLimbCount
    float hatDir[3];                  // which way the cap's tail should hang when Link stands (world, Y up, +Z forward)
    float floorY;                     // the lowest point of the model (the soles), metres
    float height;                     // the top of the model, metres
};

} // namespace skinmodel
} // namespace royale
